findings.suggestion:
EnsureDir が権限を書き換えてよいのは「自分が作ったディレクトリ」だけにする。os.Mkdir を先に試し、os.ErrExist が返ったら chmod せず、既存の権限が group/other に開いているときはエラー（またはログの警告）で知らせる形にする。

// FAIL: Bad — 既存の他人のディレクトリも 0700 にしてしまう
if err := os.MkdirAll(dir, 0o700); err != nil { ... }
if err := os.Chmod(dir, 0o700); err != nil { ... }

// Good — 作ったときだけ権限を決め、既存は検査にとどめる
if err := os.MkdirAll(filepath.Dir(dir), 0o700); err != nil { ... }
switch err := os.Mkdir(dir, 0o700); {
case err == nil:
	return os.Chmod(dir, 0o700) // 自分が作った。umask を打ち消す
case errors.Is(err, fs.ErrExist):
	info, serr := os.Lstat(dir)
	if serr != nil { return ... }
	if info.Mode()&fs.ModeSymlink != 0 {
		return fmt.Errorf("実行時ディレクトリ %s が symlink です（辿った先へ socket と flock が落ちる）", dir)
	}
	if perm := info.Mode().Perm(); perm&0o077 != 0 {
		return fmt.Errorf("既にある実行時ディレクトリ %s の権限が %o です。0700 にしてから起動してください（continuo は作っていないディレクトリの権限を書き換えません）", dir, perm)
	}
	return nil
default:
	return err
}

あわせて、claude.hook_bridge.listen が指すディレクトリを実行時ディレクトリ（socket・flock・issue ごとの設定・hook の逃がし先を全部置く場所。設計 3-23）として使う以上、「既存の共用ディレクトリを指定してはならない」ことを 5-2 のコメントと validate のエラー文言に書くこと。

