// 目的: workspace_hooks.timeout_ms が、バックグラウンドプロセスを起こす hook にも効くことを
// 確認する（効かないと片付けと run の終了が無期限に止まる）。
// 与える情報: timeout_ms を 500 にした設定と、`sleep 30 &` を含む hook。
// 成功条件: RunHook が 5 秒以内にエラーを返すこと。
func TestRunHook_バックグラウンドプロセスを起こしても時間切れで戻る(t *testing.T) {
	command := "sleep 30 & echo started"
	fx := newFixture(t, fixtureOptions{Mutate: func(cfg *config.Config) {
		cfg.WorkspaceHooks.BeforeRemove = &command
		cfg.WorkspaceHooks.TimeoutMs = 500
	}})
	prepared := prepareWorktree(t, fx, sampleIssue(188))
	start := time.Now()
	err := fx.Manager.RunHook(context.Background(), workspace.HookBeforeRemove, prepared.Path)
	if elapsed := time.Since(start); elapsed > 5*time.Second {
		t.Fatalf("timeout_ms が効いていない: %v かかった（err=%v）", elapsed, err)
	}
	if err == nil {
		t.Fatal("時間切れなのにエラーが返っていない")
	}
}

